import java.util.*;

class Solution {
    public List<Integer> preorder(TreeNode root) {
        List<Integer> answer = new ArrayList<>();
        visit(root, answer);
        return answer;
    }

    private void visit(TreeNode node, List<Integer> answer) {
        if (node == null) {
            return;
        }
        visit(node.left, answer);
        answer.add(node.val);
        visit(node.right, answer);
    }
}
